  "sim.perfume-lab.title": "香水实验室",
  "sim.perfume-lab.desc": "调配精油与芳香化合物，打造专属香型并达成品质基准。",
  "sim.detergent-lab.title": "洗涤剂实验室",
  "sim.detergent-lab.desc": "配制清洁产品——在预算内平衡表面活性剂、填充材料和性能测试。",
  "sim.skin-care-lab.title": "护肤实验室",
  "sim.skin-care-lab.desc": "开发并测试化妆品配方，符合安全标准并达到功效目标。",
  "sim.woodworking.title": "木工工坊",
