  "sim.global-kitchen.title": "环球厨房",
  "sim.global-kitchen.desc": "带领餐厅厨房：管理菜单、人员、成本，以及在各个轮班服务中提升顾客满意度。",
  "sim.chocolate-factory.title": "巧克力工厂",
  "sim.chocolate-factory.desc": "运营糖果工厂——采购可可、安排生产进度并进行质量控制。",
  "sim.solar-energy.title": "太阳能发电站",
