  "jungle.howTo.1": "你被困在丛林中——做出生存选择",
  "jungle.howTo.2": "每个选择都会以不同方式影响你的生命值（HP）和得分",
  "jungle.howTo.3": "如果你的生命值（HP）达到 0，游戏结束",
  "jungle.howTo.4": "完成全部 8 个场景以获胜！",
  "jungle.scene6": "你发现了一只受伤的鸟。你会怎么做？",
  "jungle.s6c1": "小心地把它带上——它可能会带你找到路径（+5 HP，+25 分）",
  "jungle.s6c2": "把它丢下——照顾它会耗费能量（0 HP，+10 分）",
  "jungle.scene7": "一条河挡住了你的去路。水看起来很急。",
  "jungle.s7c1": "用倒下的木头搭一只木筏（−5 HP，+40 分）",
  "jungle.s7c2": "沿水道上游走，找一个浅处渡过（+10 HP，+20 分）",
  "jungle.scene8": "你看到远处有烟雾。",
  "jungle.s8c1": "朝烟雾方向走——也许是救援！（+15 HP，+45 分）",
  "jungle.s8c2": "避开它——可能是野火（−5 HP，+15 分）",
  "jungle.scene9": "夜幕降临。你需要庇护。",
  "jungle.s9c1": "爬到高树上，躲避捕食者（+10 HP，+30 分）",
  "jungle.s9c2": "用树枝搭建地面庇护所（−5 HP，+35 分）",
  "jungle.scene10": "你发现了一种不认识的果实。你饿得厉害。",
  "jungle.s10c1": "吃掉它——你快饿死了！（−20 HP，+30 分）",
  "jungle.s10c2": "先在皮肤上试一点（0 HP，+20 分）",
  "jungle.scene11": "一条大蛇盘在路上。",
  "jungle.s11c1": "慢慢后退并寻找绕行路线（+5 HP，+30 分）",
  "jungle.s11c2": "试着把它吓走（−25 HP，+40 分）",
  "jungle.scene12": "你听到瀑布声——你的水源已经严重见底。",
  "jungle.s12c1": "顺着声音去找淡水（+20 HP，+35 分）",
  "jungle.s12c2": "无视它，继续向前走（−15 HP，+20 分）",
  "jungle.scene13": "暴风雨正迅速逼近。",
  "jungle.s13c1": "找到高处并做好掩护（+10 HP，+25 分）",
  "jungle.s13c2": "继续移动以逃离它（−10 HP，+30 分）",
  "jungle.scene14": "你发现了一个洞穴。天色越来越暗。",
  "jungle.s14c1": "进入洞穴以获得庇护（+15 HP，+30 分）",
  "jungle.s14c2": "在树下睡一觉——洞穴可能有人占用（+5 HP，+20 分）",
  "jungle.scene15": "你精疲力尽。前方的空地看起来很安全。",
  "jungle.s15c1": "休息并恢复（+20 HP，+20 分）",
  "jungle.s15c2": "继续前进——在这里休息很危险（−5 HP，+30 分）",
  "jungle.scene16": "你在树上发现了一张古老的地图。",
  "jungle.s16c1": "沿着地图的方向走（+5 HP，+40 分）",
  "jungle.s16c2": "无视它——也许已经过时了（0 HP，+10 分）",
  "jungle.scene17": "野猪正凶猛地穿过你的路。",
  "jungle.s17c1": "立刻爬到最近的树上（+5 HP，+30 分）",
  "jungle.s17c2": "站稳不动并大喊（−20 HP，+35 分）",
  "jungle.scene18": "你发现了一个废弃营地，还有物资。",
  "jungle.s18c1": "把有用的都拿走（+20 HP，+50 分）",
  "jungle.s18c2": "算了吧——说不定以后有人用得上（0 HP，+10 分）",
  "jungle.scene19": "猴子偷走了你的食物袋！",
  "jungle.s19c1": "追赶猴子（−10 HP，+40 分）",
  "jungle.s19c2": "放它走吧——不值得消耗精力（+0 HP，+15 分）",
  "jungle.scene20": "你听到头顶有直升机的声音。",
  "jungle.s20c1": "立刻点燃求救信号火！（+30 HP，+60 分）",
  "jungle.s20c2": "挥动手臂——它可能会看到你（+5 HP，+40 分）",
